typedef struct {
    int  type;
    int  value;
    char name[256];
    char str_val[1024];
} Token;

typedef struct {
    const char *input;
    int         pos;
    int         length;
    Token      *tokens;
    int         tokens_count;
} Lexer;

static int c_isdigit2(char c) { return c >= '0' && c <= '9'; }
static int c_isalpha2(char c) { return (c>='A'&&c<='Z') || (c>='a'&&c<='z'); }
static int c_isalnum2(char c) { return c_isalpha2(c) || c_isdigit2(c); }
static int c_isspace2(char c) { return c==' '||c=='\t'||c=='\n'||c=='\r'; }

static int classify_keyword(const char *n) {
    if (strcmp(n,"fn")==0)     return TOK_FN;
    if (strcmp(n,"let")==0)    return TOK_LET;
    if (strcmp(n,"var")==0)    return TOK_VAR;
    if (strcmp(n,"return")==0) return TOK_RETURN;
    if (strcmp(n,"if")==0)     return TOK_IF;
    if (strcmp(n,"else")==0)   return TOK_ELSE;
    if (strcmp(n,"while")==0)  return TOK_WHILE;
    if (strcmp(n,"for")==0)    return TOK_FOR;
    if (strcmp(n,"match")==0)  return TOK_MATCH;
    return 0;
}

Lexer* tokenize(const char *input) {
    Lexer *lex = (Lexer *)calloc(1, sizeof(Lexer));
    lex->input  = input;
    lex->length = (int)strlen(input);
    lex->tokens = (Token *)calloc(10000, sizeof(Token));

    while (lex->pos < lex->length) {
        char c = input[lex->pos];
        if (c == '\0') break;
        if (c_isspace2(c)) { lex->pos++; continue; }

        // Line comment
        if (c=='/' && lex->pos+1<lex->length && input[lex->pos+1]=='/') {
            while (lex->pos<lex->length && input[lex->pos]!='\n') lex->pos++;
            continue;
        }

        Token tok;
        memset(&tok, 0, sizeof(tok));

        if (c_isdigit2(c)) {
            while (lex->pos<lex->length && c_isdigit2(input[lex->pos]))
                tok.value = tok.value*10 + (input[lex->pos++]-'0');
            tok.type = TOK_INT;
            lex->tokens[lex->tokens_count++] = tok;
            continue;
        }

        if (c_isalpha2(c) || c=='_') {
            int len=0;
            while (lex->pos<lex->length && (c_isalnum2(input[lex->pos])||input[lex->pos]=='_'))
                tok.name[len++] = input[lex->pos++];
            int kw = classify_keyword(tok.name);
            tok.type = kw ? kw : TOK_IDENT;
            lex->tokens[lex->tokens_count++] = tok;
            continue;
        }

        if (c == '"') {
            lex->pos++;
            int len=0;
            while (lex->pos<lex->length && input[lex->pos]!='"' && len<1023) {
                if (input[lex->pos]=='\\' && lex->pos+1<lex->length) {
                    lex->pos++;
                    char e=input[lex->pos++];
                    tok.str_val[len++]=(e=='n'?'\n':(e=='t'?'\t':e));
                } else {
                    tok.str_val[len++]=input[lex->pos++];
                }
            }
            if (lex->pos<lex->length) lex->pos++;
            tok.type=TOK_STRING;
            lex->tokens[lex->tokens_count++]=tok;
            continue;
        }

        char nx = (lex->pos+1<lex->length)?input[lex->pos+1]:0;
        if      (c=='-'&&nx=='>') { tok.type=TOK_ARROW;  lex->pos+=2; }
        else if (c=='='&&nx=='=') { tok.type=TOK_EQ;     lex->pos+=2; }
        else if (c=='!'&&nx=='=') { tok.type=TOK_NE;     lex->pos+=2; }
        else if (c=='<'&&nx=='=') { tok.type=TOK_LE;     lex->pos+=2; }
        else if (c=='>'&&nx=='=') { tok.type=TOK_GE;     lex->pos+=2; }
        else if (c=='&'&&nx=='&') { tok.type=TOK_AND;    lex->pos+=2; }
        else if (c=='|'&&nx=='|') { tok.type=TOK_OR;     lex->pos+=2; }
        else if (c=='+') { tok.type=TOK_PLUS;      lex->pos++; }
        else if (c=='-') { tok.type=TOK_MINUS;     lex->pos++; }
        else if (c=='*') { tok.type=TOK_STAR;      lex->pos++; }
        else if (c=='/') { tok.type=TOK_SLASH;     lex->pos++; }
        else if (c=='=') { tok.type=TOK_ASSIGN;    lex->pos++; }
        else if (c=='!') { tok.type=TOK_NOT;       lex->pos++; }
        else if (c=='<') { tok.type=TOK_LT;        lex->pos++; }
        else if (c=='>') { tok.type=TOK_GT;        lex->pos++; }
        else if (c=='(') { tok.type=TOK_LPAREN;    lex->pos++; }
        else if (c==')') { tok.type=TOK_RPAREN;    lex->pos++; }
        else if (c=='{') { tok.type=TOK_LBRACE;    lex->pos++; }
        else if (c=='}') { tok.type=TOK_RBRACE;    lex->pos++; }
        else if (c==';') { tok.type=TOK_SEMICOLON; lex->pos++; }
        else if (c==',') { tok.type=TOK_COMMA;     lex->pos++; }
        else if (c==':') { tok.type=TOK_COLON;     lex->pos++; }
        else             { lex->pos++; continue; }
        lex->tokens[lex->tokens_count++] = tok;
    }

    Token eof; memset(&eof,0,sizeof(eof)); eof.type=TOK_EOF;
    lex->tokens[lex->tokens_count++] = eof;
    return lex;
}

