// Part 3: CODEGEN
// ============================================================

#define OUTPUT_SIZE  1000000
static char out_buf[OUTPUT_SIZE];
static int  out_pos = 0;

static void gout(const char *s) {
    if (!s) return;
    int len=(int)strlen(s);
    if (out_pos+len < OUTPUT_SIZE-1) {
        memcpy(out_buf+out_pos, s, len);
        out_pos += len;
        out_buf[out_pos] = '\0';
    }
}

static const char* fl2c(const char *fl) {
    if (!fl||!fl[0]) return "long";
    if (strcmp(fl,"i64")==0||strcmp(fl,"auto")==0) return "long";
    if (strcmp(fl,"i32")==0) return "int";
    if (strcmp(fl,"f64")==0) return "double";
    if (strcmp(fl,"bool")==0) return "int";
    if (strcmp(fl,"string")==0) return "const char*";
    return "long";
}

// Expression codegen using a simple pool
#define EP_SIZE  64
#define EP_BUFSZ 4096
static char  ep[EP_SIZE][EP_BUFSZ];
static int   ep_depth = 0;

static char* gen_expr(ASTNode *ast);

static char* ep_alloc(void) {
    char *b = ep[ep_depth % EP_SIZE];
    ep_depth++;
    b[0]='\0';
    return b;
}
static void ep_free(void) { if(ep_depth>0) ep_depth--; }

static const char* binop_str(int op) {
    switch(op){
        case TOK_PLUS:  return "+";
        case TOK_MINUS: return "-";
        case TOK_STAR:  return "*";
        case TOK_SLASH: return "/";
        case TOK_EQ:    return "==";
        case TOK_NE:    return "!=";
        case TOK_LT:    return "<";
        case TOK_GT:    return ">";
        case TOK_LE:    return "<=";
        case TOK_GE:    return ">=";
        case TOK_AND:   return "&&";
        case TOK_OR:    return "||";
    }
    return "?";
}

static char* gen_expr(ASTNode *ast) {
    char *buf = ep_alloc();
    if (!ast || ast->type==0) { strcpy(buf,"0"); return buf; }
    switch(ast->type) {
        case AST_LITERAL:
            snprintf(buf, EP_BUFSZ, "%d", ast->value);
            break;
        case AST_STRING:
            snprintf(buf, EP_BUFSZ, "\"%s\"", ast->str_val);
            break;
        case AST_IDENT:
            snprintf(buf, EP_BUFSZ, "%s", ast->name);
            break;
        case AST_CALL: {
            char args[EP_BUFSZ]="";
            for (int i=0; i<ast->children_count; i++) {
                if (i>0) strncat(args,", ",EP_BUFSZ-strlen(args)-1);
                char *a=gen_expr(ast->children[i]);
                strncat(args,a,EP_BUFSZ-strlen(args)-1);
                ep_free();
            }
            snprintf(buf, EP_BUFSZ, "%s(%s)", ast->name, args);
            break;
        }
        case AST_BINOP: {
            if (ast->op==TOK_NOT) {
                char *r=gen_expr(ast->right);
                snprintf(buf,EP_BUFSZ,"(!%s)",r);
                ep_free();
            } else {
                char *l=gen_expr(ast->left);
                char lc[EP_BUFSZ]; strncpy(lc,l,EP_BUFSZ-1); ep_free();
                char *r=gen_expr(ast->right);
                snprintf(buf,EP_BUFSZ,"(%s %s %s)",lc,binop_str(ast->op),r);
                ep_free();
            }
            break;
        }
        default: strcpy(buf,"0"); break;
    }
    return buf;
}

static void gen_stmts(ASTNode **stmts, int count, int indent);

static void ind(int level) { for(int i=0;i<level;i++) gout("    "); }

static void gen_stmt(ASTNode *ast, int indent) {
    if (!ast) return;
    switch(ast->type) {
        case AST_VAR: {
            const char *ct=fl2c(ast->type_name);
            ind(indent); gout(ct); gout(" "); gout(ast->name);
            if (ast->right) {
                gout(" = "); char *e=gen_expr(ast->right); gout(e); ep_free();
            }
            gout(";\n");
            break;
        }
        case AST_ASSIGN: {
            ind(indent); gout(ast->name); gout(" = ");
            char *e=gen_expr(ast->right); gout(e); ep_free();
            gout(";\n");
            break;
        }
        case AST_RETURN: {
            ind(indent);
            if (ast->right) {
                gout("return "); char *e=gen_expr(ast->right); gout(e); ep_free();
                gout(";\n");
            } else {
                gout("return;\n");
            }
            break;
        }
        case AST_IF: {
            ind(indent); gout("if (");
            char *c=gen_expr(ast->left); gout(c); ep_free();
            gout(") {\n");
            gen_stmts(ast->children, ast->then_count, indent+1);
            if (ast->children_count > ast->then_count) {
                ind(indent); gout("} else {\n");
                gen_stmts(ast->children+ast->then_count,
                          ast->children_count-ast->then_count, indent+1);
            }
            ind(indent); gout("}\n");
            break;
        }
        case AST_WHILE: {
            ind(indent); gout("while (");
            char *c=gen_expr(ast->left); gout(c); ep_free();
            gout(") {\n");
            gen_stmts(ast->children, ast->children_count, indent+1);
            ind(indent); gout("}\n");
            break;
        }
        case AST_EXPR_STMT: {
            if (ast->right) {
                ind(indent); char *e=gen_expr(ast->right); gout(e); ep_free();
                gout(";\n");
            }
            break;
        }
        default: break;
    }
}

static void gen_stmts(ASTNode **stmts, int count, int indent) {
    for (int i=0;i<count;i++) gen_stmt(stmts[i], indent);
}

static void gen_fwd(ASTNode *fn) {
    int is_main = (strcmp(fn->name,"main")==0);
    const char *rt = is_main ? "int" : fl2c(fn->type_name);
    gout(rt); gout(" "); gout(fn->name); gout("(");
    if (fn->params_count==0) {
        gout("void");
    } else {
        for (int i=0;i<fn->params_count;i++) {
            if (i>0) gout(", ");
            gout(fl2c(fn->param_types[i])); gout(" "); gout(fn->param_names[i]);
        }
    }
    gout(");\n");
}

static void gen_func(ASTNode *fn) {
    int is_main = (strcmp(fn->name,"main")==0);
    const char *rt = is_main ? "int" : fl2c(fn->type_name);
    gout(rt); gout(" "); gout(fn->name); gout("(");
    if (fn->params_count==0) {
        gout("void");
    } else {
        for (int i=0;i<fn->params_count;i++) {
            if (i>0) gout(", ");
            gout(fl2c(fn->param_types[i])); gout(" "); gout(fn->param_names[i]);
        }
    }
    gout(") {\n");
    gen_stmts(fn->children, fn->children_count, 1);
    gout("}\n\n");
}

static char* codegen(ASTNode *prog) {
    out_pos=0; out_buf[0]='\0'; ep_depth=0;

    gout("#include <stdio.h>\n");
    gout("#include <stdlib.h>\n");
    gout("#include <string.h>\n");
    gout("#include <stdint.h>\n\n");

    // Forward declarations
    gout("/* Forward declarations */\n");
    for (int i=0;i<prog->children_count;i++) {
        ASTNode *fn=prog->children[i];
        if (fn->type==AST_FUNC) gen_fwd(fn);
    }
    gout("\n");

    // Non-main functions first, then main
    for (int pass=0; pass<2; pass++) {
        for (int i=0;i<prog->children_count;i++) {
            ASTNode *fn=prog->children[i];
            if (fn->type!=AST_FUNC) continue;
            int is_main=(strcmp(fn->name,"main")==0);
            if (pass==0 && is_main)  continue;
            if (pass==1 && !is_main) continue;
            gen_func(fn);
        }
    }

    return out_buf;
}

// ============================================================
// Part 4: MAIN
// ============================================================

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr,"Usage: %s <input.fl> [output.c]\n",argv[0]);
        return 1;
    }
    FILE *fp=fopen(argv[1],"r");
    if (!fp) { fprintf(stderr,"Error: Cannot open '%s'\n",argv[1]); return 1; }
    fseek(fp,0,SEEK_END); long fsz=ftell(fp); fseek(fp,0,SEEK_SET);
    char *src=(char*)malloc(fsz+1);
    fread(src,1,fsz,fp); src[fsz]='\0'; fclose(fp);

