// ============================================================
// Part 6: PARSER HELPERS
// ============================================================

fn token_at(p: *Parser) -> *Token {
    var idx: i64 = p.pos;
    if idx >= p.tokens_count {
        idx = p.tokens_count - 1;
    }
    return &p.tokens[idx];
}

fn advance(p: *Parser) {
    if p.pos < p.tokens_count - 1 {
        p.pos = p.pos + 1;
    }
}

fn match_token(p: *Parser, tok_type: i64) -> i64 {
    var cur: *Token = token_at(p);
    return if cur.type == tok_type { 1 } else { 0 };
}

fn consume(p: *Parser, tok_type: i64) -> i64 {
    if match_token(p, tok_type) == 1 {
        advance(p);
        return 1;
    }
    return 0;
}

fn new_ast_node(typ: i64) -> ASTNode {
    var n: ASTNode;
    n.type = typ;
    n.value = 0;
    n.op = 0;
    n.then_count = 0;
    n.name = "";
    n.type_name = "";
    n.str_val = "";
    n.left = 0;
    n.right = 0;
    return n;
}

// Forward declarations for recursive descent parsing
