fn parse_stmt(p: *Parser) -> ASTNode;
fn parse_expr(p: *Parser) -> ASTNode;
fn parse_and_expr(p: *Parser) -> ASTNode;
fn parse_cmp(p: *Parser) -> ASTNode;
fn parse_add(p: *Parser) -> ASTNode;
fn parse_mul(p: *Parser) -> ASTNode;
fn parse_primary(p: *Parser) -> ASTNode;

fn parse_program(p: *Parser) -> ASTNode {
    var prog: ASTNode = new_ast_node(AST_PROGRAM);

    while match_token(p, TOK_FN) == 1 {
        advance(p);
        var fn_node: ASTNode = new_ast_node(AST_FUNC);

        if match_token(p, TOK_IDENT) == 1 {
            var cur: *Token = token_at(p);
            fn_node.name = cur.name;
            advance(p);
        }

        consume(p, TOK_LPAREN);

        while match_token(p, TOK_RPAREN) == 0 && match_token(p, TOK_EOF) == 0 {
            if match_token(p, TOK_IDENT) == 0 {
                break;
            }

            var param_idx: i64 = fn_node.op;  // Reuse op field for param count
            var cur: *Token = token_at(p);
            // Store param name (simplified - real version needs proper storage)
            advance(p);

            consume(p, TOK_COLON);

            if match_token(p, TOK_IDENT) == 1 {
                var type_tok: *Token = token_at(p);
                // Store param type (simplified)
                advance(p);
            }

            fn_node.op = fn_node.op + 1;  // Increment param count
            consume(p, TOK_COMMA);
        }

        consume(p, TOK_RPAREN);
        consume(p, TOK_ARROW);

        if match_token(p, TOK_IDENT) == 1 {
            var ret_type: *Token = token_at(p);
            fn_node.type_name = ret_type.name;
            advance(p);
        }

        consume(p, TOK_LBRACE);

        while match_token(p, TOK_RBRACE) == 0 && match_token(p, TOK_EOF) == 0 {
            var stmt: ASTNode = parse_stmt(p);
            // Store statement (simplified)
            fn_node.then_count = fn_node.then_count + 1;
        }

        consume(p, TOK_RBRACE);

        // Store function in program (simplified)
    }

    return prog;
}

fn parse_stmt(p: *Parser) -> ASTNode {
    if match_token(p, TOK_VAR) == 1 {
        advance(p);
        var n: ASTNode = new_ast_node(AST_VAR);

        if match_token(p, TOK_IDENT) == 1 {
            var cur: *Token = token_at(p);
            n.name = cur.name;
            advance(p);
        }

        consume(p, TOK_COLON);

        if match_token(p, TOK_IDENT) == 1 {
            var type_tok: *Token = token_at(p);
            n.type_name = type_tok.name;
            advance(p);
        }

        if consume(p, TOK_ASSIGN) == 1 {
            n.right = 0;  // placeholder
        }

        consume(p, TOK_SEMICOLON);
        return n;
    }

    if match_token(p, TOK_RETURN) == 1 {
        advance(p);
        var n: ASTNode = new_ast_node(AST_RETURN);

        if match_token(p, TOK_SEMICOLON) == 0 {
            n.right = 0;  // placeholder for expression
        }

        consume(p, TOK_SEMICOLON);
        return n;
    }

    var n: ASTNode = new_ast_node(AST_EXPR_STMT);
    n.right = 0;  // placeholder
    consume(p, TOK_SEMICOLON);
    return n;
}

fn parse_expr(p: *Parser) -> ASTNode {
    var left: ASTNode = parse_and_expr(p);
