fn is_alpha(c: i64) -> i64 {
    return (c >= 65 && c <= 90) || (c >= 97 && c <= 122);  // A-Z, a-z
}

fn is_alnum(c: i64) -> i64 {
    return is_alpha(c) || is_digit(c);
}

fn is_space(c: i64) -> i64 {
    return c == 32 || c == 9 || c == 10 || c == 13;  // space, tab, newline, CR
}

fn is_keyword(name: string) -> i64 {
    if name == "fn" {
