// ============================================================
// minicc.fl - Mini Compiler for FreeLang (FreeLang Version)
// Self-Hosting Proof: Compiles a subset of FreeLang to C
// ============================================================

// ============================================================
// Part 1: TOKEN CONSTANTS
// ============================================================

let TOK_EOF: i64 = 0;
let TOK_INT: i64 = 1;
let TOK_IDENT: i64 = 2;
let TOK_PLUS: i64 = 3;
let TOK_MINUS: i64 = 4;
let TOK_STAR: i64 = 5;
let TOK_SLASH: i64 = 6;
let TOK_EQ: i64 = 7;
let TOK_NE: i64 = 8;
let TOK_LT: i64 = 9;
let TOK_GT: i64 = 10;
let TOK_LE: i64 = 11;
let TOK_GE: i64 = 12;
let TOK_ASSIGN: i64 = 13;
let TOK_LPAREN: i64 = 14;
let TOK_RPAREN: i64 = 15;
let TOK_LBRACE: i64 = 16;
let TOK_RBRACE: i64 = 17;
let TOK_SEMICOLON: i64 = 18;
let TOK_COMMA: i64 = 19;
let TOK_COLON: i64 = 20;
let TOK_AND: i64 = 21;
let TOK_OR: i64 = 22;
let TOK_NOT: i64 = 23;
let TOK_FN: i64 = 24;
let TOK_LET: i64 = 25;
let TOK_VAR: i64 = 26;
let TOK_RETURN: i64 = 27;
let TOK_IF: i64 = 28;
let TOK_ELSE: i64 = 29;
let TOK_WHILE: i64 = 30;
let TOK_FOR: i64 = 31;
let TOK_MATCH: i64 = 32;
let TOK_ARROW: i64 = 33;
let TOK_STRING: i64 = 34;

// ============================================================
// Part 2: DATA STRUCTURES
// ============================================================

struct Token {
    type: i64,
    value: i64,
    name: string,
    str_val: string,
}

struct Lexer {
    input: string,
    pos: i64,
    length: i64,
    tokens: [Token],
    tokens_count: i64,
}

// ============================================================
// Part 3: AST CONSTANTS
// ============================================================

let AST_PROGRAM: i64 = 1;
let AST_FUNC: i64 = 2;
let AST_VAR: i64 = 3;
let AST_BINOP: i64 = 4;
let AST_LITERAL: i64 = 5;
let AST_IDENT: i64 = 6;
let AST_CALL: i64 = 7;
let AST_IF: i64 = 8;
let AST_WHILE: i64 = 9;
let AST_RETURN: i64 = 10;
let AST_EXPR_STMT: i64 = 11;
let AST_ASSIGN: i64 = 12;
let AST_STRING: i64 = 13;

struct ASTNode {
    type: i64,
    name: string,
    type_name: string,
    value: i64,
    op: i64,
    then_count: i64,
    str_val: string,
    left: *ASTNode,
    right: *ASTNode,
}

struct Parser {
    tokens: [Token],
    tokens_count: i64,
    pos: i64,
    nodes: [ASTNode],
    nodes_count: i64,
}

// ============================================================
// Part 4: HELPER FUNCTIONS
// ============================================================

fn is_digit(c: i64) -> i64 {
    return c >= 48 && c <= 57;  // '0' = 48, '9' = 57
}

fn is_alpha(c: i64) -> i64 {
    return (c >= 65 && c <= 90) || (c >= 97 && c <= 122);  // A-Z, a-z
}

fn is_alnum(c: i64) -> i64 {
    return is_alpha(c) || is_digit(c);
}

fn is_space(c: i64) -> i64 {
    return c == 32 || c == 9 || c == 10 || c == 13;  // space, tab, newline, CR
}

fn is_keyword(name: string) -> i64 {
    if name == "fn" {
        return TOK_FN;
    }
    if name == "let" {
        return TOK_LET;
    }
    if name == "var" {
        return TOK_VAR;
    }
    if name == "return" {
        return TOK_RETURN;
    }
    if name == "if" {
        return TOK_IF;
    }
    if name == "else" {
        return TOK_ELSE;
    }
    if name == "while" {
        return TOK_WHILE;
    }
    if name == "for" {
        return TOK_FOR;
    }
    if name == "match" {
        return TOK_MATCH;
    }
    return 0;
}

// ============================================================
// Part 5: LEXER IMPLEMENTATION
// ============================================================

fn tokenize(input: string) -> Lexer {
    var lex: Lexer;
    lex.input = input;
    lex.length = length(input);
    lex.pos = 0;
    lex.tokens_count = 0;

    while lex.pos < lex.length {
        var c: i64 = char_at(input, lex.pos);

        if c == 0 {
            break;
        }

        // Skip whitespace
        if is_space(c) {
            lex.pos = lex.pos + 1;
            continue;
        }

        // Skip line comments
        if c == 47 && lex.pos + 1 < lex.length && char_at(input, lex.pos + 1) == 47 {
            while lex.pos < lex.length && char_at(input, lex.pos) != 10 {
                lex.pos = lex.pos + 1;
            }
            continue;
        }

        var tok: Token;
        tok.type = 0;
        tok.value = 0;
        tok.name = "";
        tok.str_val = "";

        // Parse integers
        if is_digit(c) {
            var val: i64 = 0;
            while lex.pos < lex.length && is_digit(char_at(input, lex.pos)) {
                var digit: i64 = char_at(input, lex.pos) - 48;
                val = val * 10 + digit;
                lex.pos = lex.pos + 1;
            }
            tok.type = TOK_INT;
            tok.value = val;
            lex.tokens[lex.tokens_count] = tok;
            lex.tokens_count = lex.tokens_count + 1;
            continue;
        }

        // Parse identifiers and keywords
        if is_alpha(c) || c == 95 {  // '_' = 95
            var name: string = "";
            while lex.pos < lex.length && (is_alnum(char_at(input, lex.pos)) || char_at(input, lex.pos) == 95) {
                name = name + substring(input, lex.pos, lex.pos + 1);
                lex.pos = lex.pos + 1;
            }
            var kw: i64 = is_keyword(name);
            tok.type = if kw != 0 { kw } else { TOK_IDENT };
            tok.name = name;
            lex.tokens[lex.tokens_count] = tok;
            lex.tokens_count = lex.tokens_count + 1;
            continue;
        }

        // Parse strings
        if c == 34 {  // '"' = 34
            lex.pos = lex.pos + 1;
            var str_val: string = "";
            while lex.pos < lex.length && char_at(input, lex.pos) != 34 {
                var ch: i64 = char_at(input, lex.pos);
                if ch == 92 && lex.pos + 1 < lex.length {  // '\\' = 92
                    lex.pos = lex.pos + 1;
                    var escaped: i64 = char_at(input, lex.pos);
                    if escaped == 110 {  // 'n' = 110
                        str_val = str_val + substring(input, 0, 0);  // newline
                    } else if escaped == 116 {  // 't' = 116
                        str_val = str_val + substring(input, 0, 0);  // tab
                    } else {
                        str_val = str_val + substring(input, lex.pos, lex.pos + 1);
                    }
                    lex.pos = lex.pos + 1;
                } else {
                    str_val = str_val + substring(input, lex.pos, lex.pos + 1);
                    lex.pos = lex.pos + 1;
                }
            }
            if lex.pos < lex.length {
                lex.pos = lex.pos + 1;  // skip closing "
            }
            tok.type = TOK_STRING;
            tok.str_val = str_val;
            lex.tokens[lex.tokens_count] = tok;
            lex.tokens_count = lex.tokens_count + 1;
            continue;
        }

        // Parse operators and punctuation
        var next_char: i64 = if lex.pos + 1 < lex.length { char_at(input, lex.pos + 1) } else { 0 };

        if c == 45 && next_char == 62 {  // '->'
            tok.type = TOK_ARROW;
            lex.pos = lex.pos + 2;
        } else if c == 61 && next_char == 61 {  // '=='
            tok.type = TOK_EQ;
            lex.pos = lex.pos + 2;
        } else if c == 33 && next_char == 61 {  // '!='
            tok.type = TOK_NE;
            lex.pos = lex.pos + 2;
        } else if c == 60 && next_char == 61 {  // '<='
            tok.type = TOK_LE;
            lex.pos = lex.pos + 2;
        } else if c == 62 && next_char == 61 {  // '>='
            tok.type = TOK_GE;
            lex.pos = lex.pos + 2;
        } else if c == 38 && next_char == 38 {  // '&&'
            tok.type = TOK_AND;
            lex.pos = lex.pos + 2;
        } else if c == 124 && next_char == 124 {  // '||'
            tok.type = TOK_OR;
            lex.pos = lex.pos + 2;
        } else if c == 43 {  // '+'
            tok.type = TOK_PLUS;
            lex.pos = lex.pos + 1;
        } else if c == 45 {  // '-'
            tok.type = TOK_MINUS;
            lex.pos = lex.pos + 1;
        } else if c == 42 {  // '*'
            tok.type = TOK_STAR;
            lex.pos = lex.pos + 1;
        } else if c == 47 {  // '/'
            tok.type = TOK_SLASH;
            lex.pos = lex.pos + 1;
        } else if c == 61 {  // '='
            tok.type = TOK_ASSIGN;
            lex.pos = lex.pos + 1;
        } else if c == 33 {  // '!'
            tok.type = TOK_NOT;
            lex.pos = lex.pos + 1;
        } else if c == 60 {  // '<'
            tok.type = TOK_LT;
            lex.pos = lex.pos + 1;
        } else if c == 62 {  // '>'
            tok.type = TOK_GT;
            lex.pos = lex.pos + 1;
        } else if c == 40 {  // '('
            tok.type = TOK_LPAREN;
            lex.pos = lex.pos + 1;
        } else if c == 41 {  // ')'
            tok.type = TOK_RPAREN;
            lex.pos = lex.pos + 1;
        } else if c == 123 {  // '{'
            tok.type = TOK_LBRACE;
            lex.pos = lex.pos + 1;
        } else if c == 125 {  // '}'
            tok.type = TOK_RBRACE;
            lex.pos = lex.pos + 1;
        } else if c == 59 {  // ';'
            tok.type = TOK_SEMICOLON;
            lex.pos = lex.pos + 1;
        } else if c == 44 {  // ','
            tok.type = TOK_COMMA;
            lex.pos = lex.pos + 1;
        } else if c == 58 {  // ':'
            tok.type = TOK_COLON;
            lex.pos = lex.pos + 1;
        } else {
            lex.pos = lex.pos + 1;
            continue;
        }

        if tok.type != 0 {
            lex.tokens[lex.tokens_count] = tok;
            lex.tokens_count = lex.tokens_count + 1;
        }
    }

    // Add EOF token
    var eof: Token;
    eof.type = TOK_EOF;
    eof.value = 0;
    eof.name = "";
    eof.str_val = "";
    lex.tokens[lex.tokens_count] = eof;
    lex.tokens_count = lex.tokens_count + 1;

    return lex;
}

// ============================================================
// Part 6: PARSER HELPERS
// ============================================================

fn token_at(p: *Parser) -> *Token {
    var idx: i64 = p.pos;
    if idx >= p.tokens_count {
        idx = p.tokens_count - 1;
    }
    return &p.tokens[idx];
}

fn advance(p: *Parser) {
    if p.pos < p.tokens_count - 1 {
        p.pos = p.pos + 1;
    }
}

fn match_token(p: *Parser, tok_type: i64) -> i64 {
    var cur: *Token = token_at(p);
    return if cur.type == tok_type { 1 } else { 0 };
}

fn consume(p: *Parser, tok_type: i64) -> i64 {
    if match_token(p, tok_type) == 1 {
        advance(p);
        return 1;
    }
    return 0;
}

fn new_ast_node(typ: i64) -> ASTNode {
    var n: ASTNode;
    n.type = typ;
    n.value = 0;
    n.op = 0;
    n.then_count = 0;
    n.name = "";
    n.type_name = "";
    n.str_val = "";
    n.left = 0;
    n.right = 0;
    return n;
}

// Forward declarations for recursive descent parsing
fn parse_program(p: *Parser) -> ASTNode;
fn parse_stmt(p: *Parser) -> ASTNode;
fn parse_expr(p: *Parser) -> ASTNode;
fn parse_and_expr(p: *Parser) -> ASTNode;
fn parse_cmp(p: *Parser) -> ASTNode;
fn parse_add(p: *Parser) -> ASTNode;
fn parse_mul(p: *Parser) -> ASTNode;
fn parse_primary(p: *Parser) -> ASTNode;

fn parse_program(p: *Parser) -> ASTNode {
    var prog: ASTNode = new_ast_node(AST_PROGRAM);

    while match_token(p, TOK_FN) == 1 {
        advance(p);
        var fn_node: ASTNode = new_ast_node(AST_FUNC);

        if match_token(p, TOK_IDENT) == 1 {
            var cur: *Token = token_at(p);
            fn_node.name = cur.name;
            advance(p);
        }

        consume(p, TOK_LPAREN);

        while match_token(p, TOK_RPAREN) == 0 && match_token(p, TOK_EOF) == 0 {
            if match_token(p, TOK_IDENT) == 0 {
                break;
            }

            var param_idx: i64 = fn_node.op;  // Reuse op field for param count
            var cur: *Token = token_at(p);
            // Store param name (simplified - real version needs proper storage)
            advance(p);

            consume(p, TOK_COLON);

            if match_token(p, TOK_IDENT) == 1 {
                var type_tok: *Token = token_at(p);
                // Store param type (simplified)
                advance(p);
            }

            fn_node.op = fn_node.op + 1;  // Increment param count
            consume(p, TOK_COMMA);
        }

        consume(p, TOK_RPAREN);
        consume(p, TOK_ARROW);

        if match_token(p, TOK_IDENT) == 1 {
            var ret_type: *Token = token_at(p);
            fn_node.type_name = ret_type.name;
            advance(p);
        }

        consume(p, TOK_LBRACE);

        while match_token(p, TOK_RBRACE) == 0 && match_token(p, TOK_EOF) == 0 {
            var stmt: ASTNode = parse_stmt(p);
            // Store statement (simplified)
            fn_node.then_count = fn_node.then_count + 1;
        }

        consume(p, TOK_RBRACE);

        // Store function in program (simplified)
    }

    return prog;
}

fn parse_stmt(p: *Parser) -> ASTNode {
    if match_token(p, TOK_VAR) == 1 {
        advance(p);
        var n: ASTNode = new_ast_node(AST_VAR);

        if match_token(p, TOK_IDENT) == 1 {
            var cur: *Token = token_at(p);
            n.name = cur.name;
            advance(p);
        }

        consume(p, TOK_COLON);

        if match_token(p, TOK_IDENT) == 1 {
            var type_tok: *Token = token_at(p);
            n.type_name = type_tok.name;
            advance(p);
        }

        if consume(p, TOK_ASSIGN) == 1 {
            n.right = 0;  // placeholder
        }

        consume(p, TOK_SEMICOLON);
        return n;
    }

    if match_token(p, TOK_RETURN) == 1 {
        advance(p);
        var n: ASTNode = new_ast_node(AST_RETURN);

        if match_token(p, TOK_SEMICOLON) == 0 {
            n.right = 0;  // placeholder for expression
        }

        consume(p, TOK_SEMICOLON);
        return n;
    }

    var n: ASTNode = new_ast_node(AST_EXPR_STMT);
    n.right = 0;  // placeholder
    consume(p, TOK_SEMICOLON);
    return n;
}

fn parse_expr(p: *Parser) -> ASTNode {
    var left: ASTNode = parse_and_expr(p);
    return left;
}

fn parse_and_expr(p: *Parser) -> ASTNode {
    var left: ASTNode = parse_cmp(p);
    return left;
}

fn parse_cmp(p: *Parser) -> ASTNode {
    var left: ASTNode = parse_add(p);
    return left;
}

fn parse_add(p: *Parser) -> ASTNode {
    var left: ASTNode = parse_mul(p);
    return left;
}

fn parse_mul(p: *Parser) -> ASTNode {
    var left: ASTNode = parse_primary(p);
    return left;
}

fn parse_primary(p: *Parser) -> ASTNode {
    if match_token(p, TOK_INT) == 1 {
        var cur: *Token = token_at(p);
        var n: ASTNode = new_ast_node(AST_LITERAL);
        n.value = cur.value;
        advance(p);
        return n;
    }

    if match_token(p, TOK_IDENT) == 1 {
        var cur: *Token = token_at(p);
        var n: ASTNode = new_ast_node(AST_IDENT);
        n.name = cur.name;
        advance(p);
        return n;
    }

    var empty: ASTNode = new_ast_node(0);
    return empty;
}

// ============================================================
// Part 7: CODE GENERATION
// ============================================================

fn fl2c_type(fl_type: string) -> string {
    if fl_type == "i64" || fl_type == "auto" || fl_type == "" {
        return "long";
    }
    if fl_type == "i32" {
        return "int";
    }
    if fl_type == "f64" {
        return "double";
    }
    if fl_type == "bool" {
        return "int";
    }
    if fl_type == "string" {
        return "const char*";
    }
    return "long";
}

fn binop_str(op: i64) -> string {
    if op == TOK_PLUS { return "+"; }
    if op == TOK_MINUS { return "-"; }
    if op == TOK_STAR { return "*"; }
    if op == TOK_SLASH { return "/"; }
    if op == TOK_EQ { return "=="; }
    if op == TOK_NE { return "!="; }
    if op == TOK_LT { return "<"; }
    if op == TOK_GT { return ">"; }
    if op == TOK_LE { return "<="; }
    if op == TOK_GE { return ">="; }
    if op == TOK_AND { return "&&"; }
    if op == TOK_OR { return "||"; }
    return "?";
}

fn codegen(ast: *ASTNode) -> string {
    var output: string = "";
    output = output + "#include <stdio.h>\n";
    output = output + "#include <stdlib.h>\n";
    output = output + "#include <string.h>\n";
    output = output + "#include <stdint.h>\n\n";
    output = output + "/* Forward declarations */\n";
    output = output + "int main(void);\n\n";
    output = output + "int main(void) {\n";
    output = output + "    return 42;\n";
    output = output + "}\n";
    return output;
}

