// 간단한 키워드 기반 파서 (Claude 호출 전 전처리)
fn extract_app_name(input: string) -> string {
    // "간단한 TODO 앱 만들어줘" → "todo_app"
    // "웹 서버 만들어줘" → "web_server"
    // 매우 단순한 규칙 (실제는 Claude API로)

    if length(input) == 0 {
        return "unknown_app";
    }

    var name: string = "";

    // 첫 번째 단어를 대문자 기준으로 추출
